CREATE TABLE IF NOT EXISTS travel_visa_orders(id BIGSERIAL PRIMARY KEY,tenant_key VARCHAR(190) NOT NULL,public_ref VARCHAR(190) NOT NULL UNIQUE,service_code VARCHAR(190) NOT NULL,customer_user_id BIGINT REFERENCES users(id),amount NUMERIC(18,2) NOT NULL,currency VARCHAR(3) NOT NULL,payment_status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(payment_status IN('pending','paid','refunded')),lifecycle_status VARCHAR(32) NOT NULL DEFAULT 'awaiting_payment' CHECK(lifecycle_status IN('awaiting_payment','paid','processing','completed','cancelled')),invoice_id VARCHAR(190),processing_started_at TIMESTAMP,processing_lock VARCHAR(190),refund_lock VARCHAR(190),created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_travel_visa_orders_tenant ON travel_visa_orders(tenant_key,lifecycle_status,created_at DESC);
CREATE TABLE IF NOT EXISTS travel_visa_events(id BIGSERIAL PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES travel_visa_orders(id) ON DELETE CASCADE,event_type VARCHAR(80) NOT NULL,actor_ref VARCHAR(190) NOT NULL DEFAULT '',idempotency_key VARCHAR(190) NOT NULL DEFAULT '',payload_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(order_id,event_type,idempotency_key));
